import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.giftCards().listGiftCards(Map.of("email", "jane.doe@example.com", "is_active", "true"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("gift_cards")) {
    Map<?, ?> giftCard = (Map<?, ?>) row;
    System.out.println(giftCard.get("id") + " " + giftCard.get("code") + " " + giftCard.get("balance") + " " + giftCard.get("is_active"));
}
